// Generated by AI (UnitTest MCP)
import { describe, expect, it } from "vitest";

import { shaFromVersion, stagedIdentityMismatchWarning } from "./stage-native.mjs";

describe("shaFromVersion", () => {
  it("extracts the build sha after the crate version's + separator", () => {
    expect(shaFromVersion("0.1.7-alpha+cd2a890ad6df")).toBe("cd2a890ad6df");
  });

  it("returns undefined when the version carries no + separator", () => {
    expect(shaFromVersion("0.1.7-alpha")).toBeUndefined();
  });
});

describe("stagedIdentityMismatchWarning", () => {
  it("warns when the staged binary's build sha is not a prefix of HEAD", () => {
    const warning = stagedIdentityMismatchWarning(
      "mindleak-mcp.exe",
      "0.1.7-alpha+cd2a890ad6df",
      "f4ea939c7fbf71dcffac5890ee22cd15e11caefb"
    );
    expect(warning).toBe(
      "WARNING: staged mindleak-mcp.exe reports version 0.1.7-alpha+cd2a890ad6df " +
        "(built from cd2a890ad6df), but this checkout's HEAD is f4ea939c7fbf -- this " +
        "binary was not rebuilt at the commit being packaged and will ship stale if " +
        "this is part of a release."
    );
  });

  it("is silent when the staged binary was built at the current HEAD", () => {
    expect(
      stagedIdentityMismatchWarning(
        "mindleak-mcp.exe",
        "0.1.7-alpha+f4ea939c7fbf",
        "f4ea939c7fbf71dcffac5890ee22cd15e11caefb"
      )
    ).toBeUndefined();
  });

  it("is silent when the identity is unavailable (smoke test failed)", () => {
    expect(
      stagedIdentityMismatchWarning(
        "mindleak-mcp.exe",
        undefined,
        "f4ea939c7fbf71dcffac5890ee22cd15e11caefb"
      )
    ).toBeUndefined();
  });

  it("is silent when HEAD could not be determined", () => {
    expect(
      stagedIdentityMismatchWarning("mindleak-mcp.exe", "0.1.7-alpha+cd2a890ad6df", undefined)
    ).toBeUndefined();
  });

  it("is silent when the version carries no build sha to compare", () => {
    expect(
      stagedIdentityMismatchWarning(
        "mindleak-mcp.exe",
        "0.1.7-alpha",
        "f4ea939c7fbf71dcffac5890ee22cd15e11caefb"
      )
    ).toBeUndefined();
  });
});
